@dataclass(frozen=True, slots=True)
class MeshNode:
    """A node in the mesh network."""
    node_id: int
    address: str
    port: int
    capacity: int = 1024  # Max concurrent connections
    is_router: bool = True

    def __post_init__(self) -> None:
        if self.capacity < 1:
            raise ValueError("capacity must be positive")
        if not (0 <= self.port <= 65535):
            raise ValueError(f"Invalid port: {self.port}")


@dataclass(frozen=True, slots=True)
class MeshLink:
    """A bidirectional link between two nodes."""
    node_a: int
    node_b: int
    latency_ms: int = 1
    bandwidth_mbps: int = 100
    packet_loss: float = 0.0

    def __post_init__(self) -> None:
        if self.node_a == self.node_b:
            raise ValueError("Self-links are not allowed")
        if self.latency_ms < 0:
            raise ValueError("latency_ms must be non-negative")
        if not (0.0 <= self.packet_loss <= 1.0):
            raise ValueError("packet_loss must be in [0, 1]")


@dataclass(frozen=True, slots=True)
class MeshTopology:
    """Complete mesh network topology."""
    nodes: tuple[MeshNode, ...]
    links: tuple[MeshLink, ...]

    def __post_init__(self) -> None:
        node_ids = {n.node_id for n in self.nodes}
        for link in self.links:
            if link.node_a not in node_ids or link.node_b not in node_ids:
                raise ValueError("Link references unknown node")
        # Ensure graph is connected
        if not self._is_connected():
            raise ValueError("Mesh topology must be connected")

    def _is_connected(self) -> bool:
        """Check graph connectivity via BFS."""
        if not self.nodes:
            return True
        adjacency: dict[int, set[int]] = {n.node_id: set() for n in self.nodes}
        for link in self.links:
            adjacency[link.node_a].add(link.node_b)
            adjacency[link.node_b].add(link.node_a)

        visited: set[int] = set()
        queue = [self.nodes[0].node_id]
        while queue:
            current = queue.pop(0)
            if current in visited:
                continue
            visited.add(current)
            queue.extend(adjacency[current] - visited)
        return len(visited) == len(self.nodes)


@dataclass(frozen=True, slots=True)
class MeshMessage:
    """A message traversing the mesh."""
    message_id: int
    source: int
    destination: int
    payload: bytes
    ttl: int = 64
    priority: int = 0

    def __post_init__(self) -> None:
        if self.source == self.destination:
            raise ValueError("Source and destination must differ")
        if self.ttl < 1:
            raise ValueError("TTL must be at least 1")
        if not (0 <= self.priority <= 7):
            raise ValueError("Priority must be in [0, 7]")


# --- Search Strategies ---

def mesh_node() -> SearchStrategy[MeshNode]:
    """Generate a single mesh node."""
    return st.builds(
        MeshNode,
        node_id=node_id(),
        address=st.ip_addresses(v=4).map(str),
        port=port(),
        capacity=st.integers(min_value=1, max_value=65536),
        is_router=st.booleans(),
    )


def mesh_link(nodes: tuple[MeshNode, ...]) -> SearchStrategy[MeshLink]:
    """Generate a link between two distinct nodes."""
    node_ids = [n.node_id for n in nodes]
    return (
        st.lists(st.sampled_from(node_ids), min_size=2, max_size=2, unique=True)
        .map(tuple)
        .flatmap(lambda pair: st.builds(
            MeshLink,
            node_a=st.just(pair[0]),
            node_b=st.just(pair[1]),
            latency_ms=st.integers(min_value=0, max_value=500),
            bandwidth_mbps=st.integers(min_value=1, max_value=10000),
            packet_loss=st.floats(min_value=0.0, max_value=0.5),
        ))
    )


def mesh_topology(
    min_nodes: int = 4,
    max_nodes: int = 16,
) -> SearchStrategy[MeshTopology]:
    """Generate a connected mesh topology."""
    def build_connected(nodes: tuple[MeshNode, ...]) -> SearchStrategy[MeshTopology]:
        # Ensure connectivity by building a spanning tree first
        node_ids = [n.node_id for n in nodes]
        tree_links = [
            MeshLink(node_ids[i], node_ids[i + 1])
            for i in range(len(node_ids) - 1)
        ]
        # Add extra links for redundancy
        extra_links = st.lists(
            mesh_link(nodes),
            min_size=0,
            max_size=len(node_ids) * 2,
            unique_by=lambda l: (l.node_a, l.node_b),
        )
        return extra_links.map(
            lambda extras: MeshTopology(nodes, tuple(tree_links + extras))
        )

    return (
        st.lists(
            mesh_node(),
            min_size=min_nodes,
            max_size=max_nodes,
            unique_by=lambda n: n.node_id,
        )
        .map(tuple)
        .flatmap(build_connected)
    )


def mesh_message(
    topology: MeshTopology,
) -> SearchStrategy[MeshMessage]:
    """Generate a message between two distinct nodes in the topology."""
    node_ids = [n.node_id for n in topology.nodes]
    return (
        st.lists(st.sampled_from(node_ids), min_size=2, max_size=2, unique=True)
        .map(tuple)
        .flatmap(lambda pair: st.builds(
            MeshMessage,
            message_id=message_id(),
            source=st.just(pair[0]),
            destination=st.just(pair[1]),
            payload=st.binary(min_size=0, max_size=4096),
            ttl=st.integers(min_value=1, max_value=128),
            priority=st.integers(min_value=0, max_value=7),
        ))
    )


def adversarial_topology() -> SearchStrategy[MeshTopology]:
    """Generate pathological topologies for stress testing.

    Includes:
    - Star topologies (single point of failure)
    - Ring topologies (high latency)
    - Topologies with very high degree nodes
    """
    return st.one_of(
        # Star topology
        st.integers(min_value=4, max_value=12).map(
            lambda n: MeshTopology(
                nodes=tuple(MeshNode(i, f"10.0.0.{i}", 8000 + i) for i in range(n)),
                links=tuple(MeshLink(0, i) for i in range(1, n)),
            )
        ),
        # Ring topology
        st.integers(min_value=4, max_value=12).map(
            lambda n: MeshTopology(
                nodes=tuple(MeshNode(i, f"10.0.0.{i}", 8000 + i) for i in range(n)),
                links=tuple(MeshLink(i, (i + 1) % n) for i in range(n)),
            )
        ),
        # High-degree hub
        st.integers(min_value=4, max_value=12).flatmap(
            lambda n: st.builds(
                MeshTopology,
                nodes=st.lists(
                    mesh_node(),
                    min_size=n,
                    max_size=n,
                    unique_by=lambda x: x.node_id,
                ).map(tuple),
                links=st.lists(
                    st.builds(
                        MeshLink,
                        node_a=st.just(0),
                        node_b=st.integers(min_value=1, max_value=n - 1),
                        latency_ms=st.integers(min_value=0, max_value=100),
                        bandwidth_mbps=st.integers(min_value=1, max_value=1000),
                        packet_loss=st.floats(min_value=0.0, max_value=0.1),
                    ),
                    min_size=n - 1,
                    max_size=n - 1,
                ).map(tuple),
            )
        ),
    )


# --- Stateful Testing Support ---

class MeshRouterStateMachine:
    """Hypothesis state machine for mesh routing behavior."""

    def __init__(self, topology: MeshTopology) -> None:
        self.topology = topology
        self.routing_table: dict[int, dict[int, int]] = {}
        self.messages_in_flight: dict[int, MeshMessage] = {}
        self.delivered: dict[int, list[int]] = {}  # msg_id -> node_ids
        self.dropped: dict[int, str] = {}  # msg_id -> reason

    @st.rule(
        msg=st.builds(MeshMessage, message_id=message_id(), source=node_id(), destination=node_id(), payload=st.binary(), ttl=st.integers(min_value=1, max_value=64), priority=st.integers(min_value=0, max_value=7)),
    )
    def inject_message(self, msg: MeshMessage) -> None:
        """Inject a message into the mesh."""
        if msg.source not in {n.node_id for n in self.topology.nodes}:
            return  # Invalid source, ignore
        if msg.destination not in {n.node_id for n in self.topology.nodes}:
            return  # Invalid destination, ignore
        self.messages_in_flight[msg.message_id] = msg
        self.delivered[msg.message_id] = [msg.source]

    @st.rule(
        msg_id=st.integers(min_value=0, max_value=10000),
        next_node=st.integers(min_value=0, max_value=1023),
    )
    def route_message(self, msg_id: int, next_node: int) -> None:
        """Simulate routing a message to the next hop."""
        if msg_id not in self.messages_in_flight:
            return
        msg = self.messages_in_flight[msg_id]
        if next_node not in {n.node_id for n in self.topology.nodes}:
            return
        if next_node in self.delivered[msg_id]:
            # Loop detected - drop message
            self.dropped[msg_id] = "loop_detected"
            del self.messages_in_flight[msg_id]
            return
        if msg.ttl <= 0:
            self.dropped[msg_id] = "ttl_expired"
            del self.messages_in_flight[msg_id]
            return
        self.delivered[msg_id].append(next_node)
        if next_node == msg.destination:
            del self.messages_in_flight[msg_id]

    @st.rule()
    def check_invariants(self) -> None:
        """Verify mesh invariants hold."""
        # No duplicate delivery
        for msg_id, nodes in self.delivered.items():
            assert len(nodes) == len(set(nodes)), (
                f"Duplicate delivery for message {msg_id}"
            )

        # Bounded path length (no more than 2x node count)
        for msg_id, nodes in self.delivered.items():
            assert len(nodes) <= len(self.topology.nodes) * 2, (
                f"Path too long for message {msg_id}: {len(nodes)} hops"
            )

        # All messages either delivered or dropped with reason
        all_msg_ids = set(self.delivered.keys()) | set(self.dropped.keys())
        for msg_id in all_msg_ids:
            assert msg_id in self.delivered or msg_id in self.dropped


mesh_state_machine = st.builds(MeshRouterStateMachine, topology=mesh_topology())